for(let s=0;s<3;s++){let result=await sweep(100);if(result!==100)throw Error(`stage ${s} stuck at ${result}%`);await p.locator('#completeBtn').click();}
for(let i=0;i<4;i++){if(i)await p.locator(`.catalog-item[data-choice="${i}"]`).click();await p.mouse.click(534,347);await p.waitForTimeout(30);console.log('decor choice',i,'progress',await pct())}
console.log('finish button',await p.locator('#completeBtn').isEnabled(),'cash',await p.locator('#cash').innerText(),'spent',await p.locator('#spent').innerText(),'errors',errors);
await p.locator('#completeBtn').click();console.log('finish modal open',await p.locator('#finishModal').getAttribute('class'));
for(const v of [{width:390,height:844},{width:768,height:1024},{width:1024,height:768},{width:1280,height:800}]){await p.setViewportSize(v);await p.waitForTimeout(200);console.log('viewport',v.width+'x'+v.height,'overflow',await p.evaluate(()=>[document.documentElement.scrollWidth-document.documentElement.clientWidth,document.documentElement.scrollHeight-document.documentElement.clientHeight]),'canvas',await p.locator('canvas').boundingBox(),'mobile controls',await p.locator('#mobileNext').isVisible())}
await p.locator('#restartBtn').click();await p.waitForTimeout(400);console.log('restart',await p.locator('#progressText').innerText(),await p.locator('#inspectorTitle').innerText());await b.close();
EOF

